-- The 56 products from the WooCommerce site (scraped 20 Oct 2026), loaded as
-- 'awaiting_client': no price, VAT, pack size or allergens. RLS hides them from
-- the public until each is completed and signed off. Re-runnable.
on conflict (slug) do update set
  name = excluded.name,
  own_brand = excluded.own_brand,
  legacy_categories = excluded.legacy_categories;
